// Confere a assinatura HMAC (horário + corpo bruto). Pedido velho ou adulterado vira valid=false,
// e o fluxo responde 401: o outbox da API nunca marca como entregue o que não foi processado.
const crypto = require('crypto');
const secret = $env.H2D_HMAC_SECRET;
if (!secret) return [{ json: { valid: false, reason: 'H2D_HMAC_SECRET não configurado' } }];
const headers = $input.first().json.headers || {};
const ts = headers['x-h2d-timestamp'];
const sig = String(headers['x-h2d-signature'] || '');
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.`).update(raw).digest('hex');
const a = Buffer.from(sig);
const b = Buffer.from(expected);
const signatureOk = a.length === b.length && crypto.timingSafeEqual(a, b);
const age = Math.abs(Date.now() / 1000 - Number(ts));
if (!ts || !signatureOk || !(age <= 300)) return [{ json: { valid: false, reason: 'Assinatura inválida' } }];
const event = JSON.parse(raw.toString('utf8'));
const store = $getWorkflowStaticData('global');
const seen = store.seen || [];
return [{ json: { valid: true, duplicate: seen.includes(event.event_id), event } }];

// Decide para quem e o que enviar, conforme o tipo do evento.
const e = $json.event;
const p = e.payload || {};
const leader = $env.TI_LEADER_EMAIL || '';
const base = ($env.H2D_BASE_URL || '').replace(/\/$/, '');
const link = base ? `\n\nAbrir no sistema: ${base}/chamados` : '';
let to = '';
let cc = '';
let subject = '';
let text = '';
let htmlText = '';
let actionUrl = '';
let actionLabel = '';
if (e.type === 'ticket.created') {
  to = (p.assignee && p.assignee.email) || leader;
  if (p.notify_leader && leader && leader !== to) cc = leader;
  subject = `[H2D] Novo chamado ${p.code}${p.priority ? ' (' + p.priority + ')' : ''}: ${p.summary}`;
  text = `Novo chamado ${p.code}\nPrioridade: ${p.priority || 'não definida'}\nSolicitante: ${p.requester && p.requester.name}\nResponsável: ${p.assignee ? p.assignee.name : 'ninguém ainda (triagem manual)'}\nPrazo de resolução: ${p.resolution_due || 'não definido'}\n\n${p.summary}${link}`;
} else if (e.type === 'ticket.assigned') {
  to = (p.assignee && p.assignee.email) || '';
  subject = `[H2D] Chamado ${p.code} atribuído a você`;
  text = `O chamado ${p.code} foi atribuído a você.\nPrioridade: ${p.priority || 'não definida'}\nSolicitante: ${p.requester && p.requester.name}\n\n${p.summary}${link}`;
} else if (e.type === 'ticket.resolved') {
  to = (p.requester && p.requester.email) || '';
  subject = `[H2D] Seu chamado ${p.code} foi resolvido`;
  text = `Olá! O chamado ${p.code} (${p.summary}) foi resolvido pela equipe de TI.\nSe o problema voltar, responda no próprio chamado.`;
} else if (e.type === 'ticket.sla_alert') {
  const estouro = p.level === 100;
  to = (p.assignee && p.assignee.email) || leader;
  if (estouro && leader && leader !== to) cc = leader;
  subject = estouro ? `[H2D] SLA ESTOURADO: ${p.code} (${p.summary})` : `[H2D] SLA em risco (75% do prazo): ${p.code}`;
  text = `${estouro ? 'O prazo de resolução ESTOUROU' : 'O prazo de resolução passou de 75%'} no chamado ${p.code}.
Prioridade: ${p.priority || 'não definida'}
Responsável: ${p.assignee ? p.assignee.name : 'ninguém ainda'}
Prazo: ${p.resolution_due || 'não definido'}

${p.summary}${link}`;
} else if (e.type === 'user.invited') {
  to = p.email || '';
  actionUrl = `${base}/definir-senha?token=${encodeURIComponent(p.token || '')}`;
  subject = '[H2D] Defina sua senha de acesso';
  text = `Olá, ${p.name}!\n\nSua conta no H2D TI foi criada. Para definir sua senha e entrar, abra o link abaixo:\n\n${actionUrl}\n\nO link vale por ${p.valid_hours} horas e só pode ser usado uma vez. Se ele vencer, peça um novo ao administrador.`;
  actionLabel = 'Definir minha senha';
  htmlText = `Olá, ${p.name}!\n\nSua conta no H2D TI foi criada. Para definir sua senha e entrar no sistema, use o botão abaixo.\n\nO link vale por ${p.valid_hours} horas e só pode ser usado uma vez. Se ele vencer, peça um novo ao administrador.`;
  // Sem endereço do sistema ou sem token, falha alto: o outbox tenta de novo, nada se perde calado.
  if (!base || !p.token) throw new Error('Convite sem H2D_BASE_URL ou sem token');
}
// E-mail com o visual do app (tema escuro, verde de ação). Estilos inline: clientes de e-mail ignoram CSS externo.
if (!actionUrl && base && e.type.startsWith('ticket.')) { actionUrl = `${base}/chamados`; actionLabel = 'Abrir no sistema'; }
if (!htmlText) htmlText = link ? text.replace(link, '') : text;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const title = subject.replace(/^\[H2D\]\s*/, '');
const paragraphs = htmlText.split(/\n\n+/).map((par) => `<p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#ededed;">${esc(par).replace(/\n/g, '<br>')}</p>`).join('');
const button = actionUrl ? `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:8px 0;"><tr><td style="background:#3ddc97;border-radius:8px;"><a href="${esc(actionUrl)}" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:600;color:#06281a;text-decoration:none;">${esc(actionLabel)}</a></td></tr></table>` : '';
const fallback = e.type === 'user.invited' ? `<p style="margin:16px 0 0;font-size:12px;line-height:1.5;color:#a1a1a1;word-break:break-all;">Se o botão não funcionar, copie este endereço no navegador:<br>${esc(actionUrl)}</p>` : '';
const html = `<!doctype html><html lang="pt-BR"><body style="margin:0;padding:0;background:#0a0a0a;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#0a0a0a;"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;font-family:Inter,-apple-system,'Segoe UI',Roboto,Arial,sans-serif;"><tr><td style="padding:0 0 20px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td width="36" height="36" align="center" style="background:#3ddc97;border-radius:8px;font-weight:700;font-size:13px;color:#06281a;">H2D</td><td style="padding-left:12px;"><div style="font-size:16px;font-weight:700;color:#ededed;">H2D TI</div><div style="font-size:12px;color:#a1a1a1;">Gestão de atendimento</div></td></tr></table></td></tr><tr><td style="background:#141414;border:1px solid #2e2e2e;border-radius:12px;padding:28px;"><h1 style="margin:0 0 16px;font-size:20px;line-height:1.3;color:#ededed;">${esc(title)}</h1>${paragraphs}${button}${fallback}</td></tr><tr><td style="padding:16px 4px 0;font-size:12px;color:#a1a1a1;">Mensagem automática do H2D TI. Não responda a este e-mail.</td></tr></table></td></tr></table></body></html>`;
return [{ json: { event_id: e.event_id, type: e.type, send: Boolean(to), to, cc, subject, text, html } }];

// Só depois do envio o evento vira "processado": se o e-mail falhar, a nova tentativa do outbox passa.
const id = $('Montar aviso').first().json.event_id;
const store = $getWorkflowStaticData('global');
const seen = store.seen || [];
if (!seen.includes(id)) seen.push(id);
store.seen = seen.slice(-500);
return [{ json: { ok: true, event_id: id } }];
